  "Descall was founded by Demir Sarp Kurtlar, who remains the owner and CEO.": "Descall wurde von Demir Sarp Kurtlar gegründet, der weiterhin Inhaber und CEO ist.",
  "Descall wins for squads that want DMs, groups, WebRTC voice/video, and screen share without Nitro. It is not trying to replace every public Discord server.": "Descall gewinnt für Squads, die DMs, Gruppen, WebRTC-Sprache/-Video und Bildschirmübertragung ohne Nitro wollen. Es versucht nicht, jeden öffentlichen Discord-Server zu ersetzen.",
