  "How small communities pick a Discord alternative: servers, roles, invites, voice hangouts, and when to stay on Discord.": "Wie kleine Communitys eine Discord-Alternative wählen: Server, Rollen, Einladungen, Sprachtreffen – und wann man bei Discord bleibt.",
