  "Issue action": "Maßnahme verhängen",
  "Issue category-based bans and app timeouts with a message the user will see.": "Verhänge kategoriebasierte Banns und App-Timeouts mit einer Nachricht, die der Nutzer sieht.",
  "It depends on job-to-be-done. For friend voice + servers, Descall. For huge communities, Discord. For pure voice servers, TeamSpeak/Mumble. See our alternatives hub for a fuller comparison.": "Das hängt von der Aufgabe ab. Für Sprachchat mit Freunden + Server: Descall. Für riesige Communitys: Discord. Für reine Sprachserver: TeamSpeak/Mumble. Einen ausführlicheren Vergleich findest du in unserem Alternativen-Hub.",
  "It depends on the job. If you need mega-servers and a huge bot store, Discord still leads. If you want free HD voice, screen share, and real servers without a Nitro wall, Descall is a strong free Discord alternative.": "Das hängt von der Aufgabe ab. Wenn du Mega-Server und einen riesigen Bot-Store brauchst, liegt Discord weiter vorn. Wenn du kostenlosen HD-Sprachchat, Bildschirmübertragung und echte Server ohne Nitro-Schranke willst, ist Descall eine starke kostenlose Discord-Alternative.",
