  "More options": "Weitere Optionen",
  "More reactions": "Weitere Reaktionen",
  "Most Discord replacement attempts fail when voice feels worse. Descall invests in WebRTC calls, TURN, and screen-share presets so nightly voice stays easy.": "Die meisten Versuche, Discord zu ersetzen, scheitern, wenn sich der Sprachchat schlechter anfühlt. Descall investiert in WebRTC-Anrufe, TURN und Vorgaben für die Bildschirmübertragung, damit der abendliche Sprachchat einfach bleibt.",
  "Most community platforms either drown you in mega-server chrome or skip structure entirely. Descall gives you real servers with categories, text/voice/stage channels, roles, channel overrides, and ready-made community templates, so a clan, class, or creator circle can launch organized in minutes.": "Die meisten Community-Plattformen ertränken dich entweder im Mega-Server-Ballast oder verzichten ganz auf Struktur. Descall gibt dir echte Server mit Kategorien, Text-/Sprach-/Bühnenkanälen, Rollen, Kanalüberschreibungen und fertigen Community-Vorlagen – so kann ein Clan, eine Klasse oder ein Creator-Kreis in wenigen Minuten organisiert starten.",
  "Most friend groups feel settled within two weeks of moving evening voice.": "Die meisten Freundesgruppen haben sich innerhalb von zwei Wochen eingelebt, nachdem sie den abendlichen Sprachchat umgezogen haben.",
  "Most groups dual-stack for a month, then realize 90% of pings happen on Descall. That’s a healthy Discord replacement path, no big-bang migration required.": "Die meisten Gruppen nutzen einen Monat lang beides und merken dann, dass 90 % der Pings auf Descall passieren. Das ist ein gesunder Weg, Discord zu ersetzen – ganz ohne großen Stichtag.",
  "Most groups want both. Descall pairs DMs and servers with the same voice stack so you are not juggling two apps.": "Die meisten Gruppen wollen beides. Descall kombiniert DMs und Server mit derselben Sprachtechnik, damit du nicht zwischen zwei Apps jonglieren musst.",
