  "No. Core calls are free. There is no Nitro-style paywall on talking to friends.": "Nein. Anrufe sind kostenlos. Es gibt keine Nitro-artige Bezahlschranke fürs Reden mit Freunden.",
  "No. Core chat, servers, and calls are free. DesCoin only buys cosmetics.": "Nein. Chat, Server und Anrufe sind kostenlos. Mit DesCoin kaufst du nur Kosmetik.",
  "No. Descall makes the product, and the article states where Discord still wins, bots, giant communities, and broader historic client coverage.": "Nein. Descall entwickelt das Produkt, und der Artikel nennt, wo Discord weiterhin gewinnt: Bots, riesige Communitys und eine historisch breitere Client-Abdeckung.",
  "No. Slack, Telegram, and TeamSpeak overlap only on some jobs. Compare by voice, servers, and whether core features are free.": "Nein. Slack, Telegram und TeamSpeak überschneiden sich nur bei manchen Aufgaben. Vergleiche nach Sprachchat, Servern und danach, ob die Kernfunktionen kostenlos sind.",
