  "People": "Personen",
  "People in voice": "Leute im Sprachkanal",
  "People saying “apps like Discord” usually want chat + persistent groups + voice. Some also want screen share. Descall covers that core. It does not try to clone every Discord bot and Stage feature, and that focus is the product.": "Wer „Apps wie Discord“ sagt, will meistens Chat + dauerhafte Gruppen + Sprachchat. Manche wollen auch Bildschirmübertragung. Descall deckt diesen Kern ab. Es versucht nicht, jeden Discord-Bot und jede Bühnenfunktion zu kopieren – und genau dieser Fokus ist das Produkt.",
  "People you may know, ranked by mutual friends and shared groups.": "Leute, die du vielleicht kennst, sortiert nach gemeinsamen Freunden und Gruppen.",
  "Performance": "Leistung",
  "Performance Impact": "Leistungsbedarf",
