  "PiP / minimize-friendly call UX": "Anruf-UX mit PiP und Minimieren",
  "Pick Descall for nightly friend voice and servers without Nitro. Keep Discord if you still depend on a large bot marketplace or huge public servers.": "Wähle Descall für abendlichen Sprachchat mit Freunden und Server ohne Nitro. Bleib bei Discord, wenn du noch auf einen großen Bot-Marktplatz oder riesige öffentliche Server angewiesen bist.",
  "Pick Descall when your group wants a lighter Discord alternative for chat, voice, and screen share. Keep Discord when you still run large public communities and bots.": "Wähle Descall, wenn deine Gruppe eine leichtere Discord-Alternative für Chat, Sprachchat und Bildschirmübertragung will. Bleib bei Discord, wenn du noch große öffentliche Communitys und Bots betreibst.",
  "Pick Gaming, Friends, or Community templates so roles and staff rooms appear ready. Invite codes replace Discord’s invite links.": "Wähle die Vorlagen Gaming, Freunde oder Community, damit Rollen und Team-Räume fertig dastehen. Einladungscodes ersetzen die Einladungslinks von Discord.",
  "Pick a DM or group, then start a voice or video call": "Wähle eine DM oder Gruppe und starte dann einen Sprach- oder Videoanruf",
  "Pick a GIF": "GIF auswählen",
  "Pick a friend, start a DM, or create a group, Descall keeps it light.": "Wähle einen Freund, starte eine DM oder erstelle eine Gruppe – Descall hält es einfach.",
