  "Start from a template or an empty server. Templates include text channels, voice channels, and roles such as Admin, Moderator, and Member.": "Starte mit einer Vorlage oder einem leeren Server. Vorlagen enthalten Textkanäle, Sprachkanäle und Rollen wie Admin, Moderator und Mitglied.",
  "Start from scratch": "Bei null anfangen",
  "Start from scratch or pick a template packed with roles, text & voice channels, topics, slowmode, and staff permission overrides, gaming, community, study, friends, or streaming.": "Starte von Grund auf oder wähle eine Vorlage voller Rollen, Text- & Sprachkanäle, Themen, Slowmode und Team-Berechtigungsüberschreibungen – Gaming, Community, Lernen, Freunde oder Streaming.",
