  "Start using apps and games to see them here": "Nutze Apps und Spiele, damit sie hier erscheinen",
  "Start with /alternatives and /compare/discord, or read the Discord competitors blog post.": "Starte mit /alternatives und /compare/discord oder lies den Blogbeitrag über Discord-Konkurrenten.",
  "Start with your real job-to-be-done: friend DMs, group voice, screen share, or a gaming server. If you need mega-servers and bot ecosystems, Discord still leads. If you want a lighter Discord alternative that keeps communication free, Descall is built for you.": "Fang mit dem an, was du wirklich brauchst: DMs mit Freunden, Gruppen-Sprachchat, Bildschirmübertragung oder einen Gaming-Server. Wenn du Mega-Server und Bot-Ökosysteme brauchst, liegt Discord immer noch vorn. Wenn du eine leichtere Discord-Alternative willst, bei der Kommunikation kostenlos bleibt, ist Descall für dich gemacht.",
