  "Themes, frames, and effects via DesCoin. Core chat, servers, and calls stay free forever.": "Themes, Rahmen und Effekte über DesCoin. Chat, Server und Anrufe bleiben für immer kostenlos.",
  "Then enable notifications for calls and DMs.": "Aktiviere dann Benachrichtigungen für Anrufe und DMs.",
  "There is no bulk Discord history importer today. Pin key links, rebuild channels, and start fresh voice nights on Descall.": "Einen Massenimport des Discord-Verlaufs gibt es derzeit nicht. Pinne wichtige Links an, bau Kanäle neu auf und starte frische Sprachabende auf Descall.",
  "They answered on a locked iPhone but couldn't join in time. Try calling again.": "Der Anruf wurde auf einem gesperrten iPhone angenommen, aber der Beitritt hat nicht rechtzeitig geklappt. Ruf noch mal an.",
  "This account doesn’t have an email address, so we can’t send a reset code. Contact support and we’ll help you recover access.": "Für dieses Konto ist keine E-Mail-Adresse hinterlegt, daher können wir keinen Code senden. Wende dich an den Support, dann helfen wir dir, wieder Zugriff zu bekommen.",
  "This account has no email on file. Contact support@descall.com to recover access.": "Für dieses Konto ist keine E-Mail hinterlegt. Wende dich an support@descall.com, um wieder Zugriff zu bekommen.",
  "This account is closed because the account holder is under 13. Account deletion has started.": "Dieses Konto ist geschlossen, weil die Kontoinhaberin oder der Kontoinhaber unter 13 Jahre alt ist. Die Kontolöschung wurde eingeleitet.",
  "This account's username is tied to admin access and can't be changed.": "Der Benutzername dieses Kontos ist an den Admin-Zugang gebunden und kann nicht geändert werden.",
