  "Voice, video, and screen share": "Sprache, Video und Bildschirmübertragung",
  "Voice-first classics. Weak for modern chat, presence, and mobile.": "Klassiker mit Fokus auf Sprache. Schwach bei modernem Chat, Präsenz und Mobil.",
  "Voice/video and screen share for hangouts": "Sprache/Video und Bildschirmübertragung für Treffen",
  "Volume": "Lautstärke",
  "Waiting for others to join…": "Warte, bis andere beitreten…",
  "Waiting for screen…": "Warte auf Bildschirm…",
  "Waiting for the call…": "Warte auf den Anruf…",
  "Waiting…": "Warte…",
  "Want a voice chat alternative to Discord without Nitro friction? Descall uses WebRTC voice/video with TURN support, incoming-call UX, PiP, and screen-share quality presets, free for core communication.": "Willst du eine Sprachchat-Alternative zu Discord ohne Nitro-Reibung? Descall nutzt WebRTC-Sprache/-Video mit TURN-Unterstützung, durchdachte eingehende Anrufe, PiP und Qualitätsvorgaben für die Bildschirmübertragung – kostenlos für die Kernkommunikation.",
  "Warn": "Verwarnen",
  "Warning": "Warnung",
  "Watching": "Schaut",
  "Watching something": "Schaut etwas",
  "Watching this flip…": "Schaut diesem Münzwurf zu…",
  "Watching this hand…": "Du schaust bei dieser Hand zu…",
  "Watching this spin…": "Du schaust bei diesem Dreh zu…",
  "We are (players already)": "Wir sind (Spieler bisher)",
  "We care about your privacy": "Deine Privatsphäre ist uns wichtig",
  "We don’t claim Discord’s bot marketplace, Stage events, or every platform client. Honesty ranks better than doorway pages.": "Wir behaupten nicht, Discords Bot-Marktplatz, Bühnen-Events oder jeden Plattform-Client zu haben. Ehrlichkeit rankt besser als Brückenseiten.",
  "We focus on real-time messaging, group voice/video, screen share, and a polished desktop experience, without turning private chats into SEO landings.": "Wir konzentrieren uns auf Echtzeit-Messaging, Gruppen-Sprache/-Video, Bildschirmübertragung und ein ausgefeiltes Desktop-Erlebnis – ohne private Chats in SEO-Landingpages zu verwandeln.",
  "We got your note. We’ll reply at the email you gave.": "Wir haben deine Nachricht erhalten. Wir antworten an die angegebene E-Mail-Adresse.",
  "We now ask everyone for their date of birth so we can keep Descall safe and show the right features for your age.": "Wir fragen jetzt alle nach ihrem Geburtsdatum, damit Descall sicher bleibt und du die passenden Funktionen für dein Alter bekommst.",
  "We only use essential cookies; we ask for your permission for analytics.": "Wir verwenden nur notwendige Cookies; für Analysen fragen wir dich um Erlaubnis.",
  "We only use the cookies Descall needs to run. We ask for your permission for analytics cookies.": "Wir verwenden nur die Cookies, die Descall zum Funktionieren braucht. Für Analyse-Cookies fragen wir dich um Erlaubnis.",
  "We review every submission and use it to make Descall better.": "Wir prüfen jede Einsendung und nutzen sie, um Descall besser zu machen.",
  "We scored apps on free core chat/calls, voice quality path, server tools, desktop/mobile reality, and whether friend groups can switch in a week, not on who has the longest feature checklist.": "Wir haben Apps danach bewertet, ob Chat und Anrufe kostenlos sind, wie gut die Sprachqualität ist, welche Server-Tools es gibt, wie Desktop und Mobil in der Praxis laufen und ob Freundesgruppen in einer Woche wechseln können – nicht danach, wer die längste Funktionsliste hat.",
  "We sent a 6-digit code to your email.": "Wir haben einen 6-stelligen Code an deine E-Mail gesendet.",
  "We use infrastructure providers (hosting, database, authentication) as processors. Content you send is visible to the recipients you choose (DMs, groups).": "Wir nutzen Infrastrukturanbieter (Hosting, Datenbank, Authentifizierung) als Auftragsverarbeiter. Inhalte, die du sendest, sind für die von dir gewählten Empfänger sichtbar (DMs, Gruppen).",
  "We use this data to provide chat and calls, keep the service secure, improve reliability, and communicate important product updates. We do not sell your personal information.": "Wir nutzen diese Daten, um Chat und Anrufe bereitzustellen, den Dienst sicher zu halten, die Zuverlässigkeit zu verbessern und über wichtige Produkt-Updates zu informieren. Wir verkaufen deine personenbezogenen Daten nicht.",
  "We'll send a code to this email to verify it. It keeps your account safe: recovery, sign-in codes and two-factor authentication.": "Wir schicken einen Code an diese E-Mail-Adresse, um sie zu bestätigen. Das schützt dein Konto: Wiederherstellung, Anmeldecodes und Zwei-Faktor-Authentifizierung.",
  "Weak": "Schwach",
  "Weak connection": "Schwache Verbindung",
  "Wear": "Tragen",
  "Wear it right after buying": "Direkt nach dem Kauf tragen",
  "Web + Windows + Android so members can join anywhere": "Web + Windows + Android, damit Mitglieder überall beitreten können",
  "Web / desktop / mobile FCM": "Web / Desktop / mobiles FCM",
  "Web and API traffic use HTTPS/TLS. Real-time media uses WebRTC with DTLS/SRTP between peers when a call is established.": "Web- und API-Verkehr nutzt HTTPS/TLS. Echtzeit-Medien nutzen WebRTC mit DTLS/SRTP zwischen den Teilnehmern, sobald ein Anruf aufgebaut ist.",
  "Web and API traffic use HTTPS/TLS. Real-time media uses WebRTC with DTLS/SRTP between peers when a call is established. Descall does not claim default end-to-end encryption for all message history stored on the server, messages are encrypted in transit and stored so your devices can load chat history.": "Web- und API-Verkehr laufen über HTTPS/TLS. Echtzeitmedien nutzen WebRTC mit DTLS/SRTP zwischen den Teilnehmern, sobald ein Anruf aufgebaut ist. Descall behauptet keine standardmäßige Ende-zu-Ende-Verschlüsselung für den gesamten auf dem Server gespeicherten Nachrichtenverlauf; Nachrichten werden bei der Übertragung verschlüsselt und gespeichert, damit deine Geräte den Chatverlauf laden können.",
  "Web app": "Web-App",
  "WebRTC": "WebRTC",
  "WebRTC voice for DMs, groups, and server lobbies with noise controls when you need them.": "WebRTC-Sprachchat für DMs, Gruppen und Server-Lobbys mit Rauschunterdrückung, wenn du sie brauchst.",
  "WebRTC voice/video with TURN support, incoming call UX, PiP, and screen-share quality controls. A lighter Discord alternative when you want clean calls inside servers or DMs.": "WebRTC-Sprache/-Video mit TURN-Unterstützung, durchdachte eingehende Anrufe, PiP und Qualitätssteuerung für die Bildschirmübertragung. Eine leichtere Discord-Alternative, wenn du saubere Anrufe in Servern oder DMs willst.",
  "Websites like Discord": "Websites wie Discord",
  "Websites like Discord vs installable apps": "Websites wie Discord vs. installierbare Apps",
  "Week 1: create a Descall group and move evening voice. Week 2: move media sharing and your gaming server if you play together. Most friend groups don’t need a full export, they need a new habit.": "Woche 1: Erstelle eine Descall-Gruppe und zieh den abendlichen Sprachchat um. Woche 2: Zieh das Teilen von Medien und euren Gaming-Server um, wenn ihr zusammen spielt. Die meisten Freundesgruppen brauchen keinen vollständigen Export, sondern eine neue Gewohnheit.",
  "Week 1: create a Descall group, move evening voice. Week 2: move your server and screen-share sessions. Keep Discord for public servers you still enjoy.": "Woche 1: Erstelle eine Descall-Gruppe und zieh den abendlichen Sprachchat um. Woche 2: Zieh deinen Server und die Bildschirmübertragungs-Sessions um. Behalte Discord für öffentliche Server, die dir noch Spaß machen.",
