  "Windows users should install the desktop client for fewer browser tab mishaps. Android and web cover the rest of the group.": "Windows-Nutzer sollten den Desktop-Client installieren, damit es weniger Pannen mit Browser-Tabs gibt. Android und Web decken den Rest der Gruppe ab.",
  "Won": "Gewonnen",
  "Work-first chat. Huddles exist, but gamers looking for a Discord alternative usually want evenings, not tickets.": "Chat mit Fokus auf Arbeit. Huddles gibt es zwar, aber Gamer auf der Suche nach einer Discord-Alternative wollen meistens Feierabende, keine Tickets.",
