  "Your friend group doesn’t need a mega-server. Descall is a Discord alternative for friends: real-time DMs, groups, presence, and free voice/video so the people you actually call stay one tap away.": "Deine Freundesgruppe braucht keinen Mega-Server. Descall ist eine Discord-Alternative für Freunde: Echtzeit-DMs, Gruppen, Präsenz und kostenlose Sprach-/Videoanrufe, damit die Leute, die du wirklich anrufst, nur einen Tipp entfernt sind.",
